  Lemma Z_carved_sh : forall c1 x lo' k a, carved st c1 x -> x <= lo' -> lo' + 8 * k <= x + class_size c1 -> lo' mod 8 = 0 -> 0 <= k ->
    sh lo' <= a < sh lo' + k -> outside W a.
